	local bean = screenGui:WaitForChild("bean")

	local TweenService = game:GetService("TweenService")

	local centerPos = UDim2.new(0.5, -bean.AbsoluteSize.X/2, 0.5, -bean.AbsoluteSize.Y/2)
	local bottomLeftPos = UDim2.new(0, 0, 1, -bean.AbsoluteSize.Y)

	local tweenInfo = TweenInfo.new(1.5, Enum.EasingStyle.Quad, Enum.EasingDirection.Out)

	local tweenCenter = TweenService:Create(bean, tweenInfo, {Position = centerPos})
	local tweenBottomLeft = TweenService:Create(bean, tweenInfo, {Position = bottomLeftPos})

	local function moveSmooth()
		tweenCenter:Play()
		tweenCenter.Completed:Wait()
		tweenBottomLeft:Play()
	end

	moveSmooth()

end;
